"""Writes tools/stats/cases_gen.txt: the generic pdf, cdf, icdf and random functions."""
import os
here = os.path.dirname(os.path.abspath(__file__))
L = ["# generated by make_gen_cases.py"]
fams = [("Normal", "1,2"), ("norm", "0.5,2"), ("Uniform", "0,3"), ("unif", "0,3"), ("Beta", "2,3"), ("Binomial", "10,0.3"), ("bino", "10,0.3"), ("Chi-square", "4"), ("chi2", "4"), ("Exponential", "2"), ("exp", "2"), ("Extreme Value", "0,2"), ("ev", "0,2"),
        ("F", "3,5"), ("Gamma", "2,3"), ("gam", "2,3"), ("Generalized Extreme Value", "0.2,1,0"), ("gev", "0.2,1,0"), ("Generalized Pareto", "0.2,1,0"), ("gp", "0.2,1,0"), ("Geometric", "0.3"), ("geo", "0.3"), ("Hypergeometric", "20,5,8"), ("hyge", "20,5,8"),
        ("Lognormal", "0.1,0.8"), ("logn", "0.1,0.8"), ("Negative Binomial", "3,0.4"), ("nbin", "3,0.4"), ("Poisson", "3"), ("poiss", "3"), ("Rayleigh", "1.5"), ("rayl", "1.5"), ("T", "4"), ("Discrete Uniform", "10"), ("unid", "10"), ("Weibull", "2,1.5"), ("wbl", "2,1.5"),
        ("Noncentral Chi-square", "4,2"), ("ncx2", "4,2"), ("Noncentral t", "4,1"), ("nct", "4,1"), ("Noncentral F", "3,5,2"), ("ncf", "3,5,2")]
for n, p in fams:
    L.append(f"r = pdf('{n}',[0.2 0.5 1 2 3],{p});")
    L.append(f"r = cdf('{n}',[0.2 0.5 1 2 3],{p});")
for n, p in fams[:20]:
    L.append(f"r = icdf('{n}',[0.1 0.5 0.9],{p});")
for c in ["pdf('normal',0.5)", "pdf('normal',[0 1],0)", "pdf('normal',0.5,0,1,2)", "pdf('foo',1)", "pdf('n',1)", "pdf('e',1)", "pdf(1,2)", "pdf('norm')", "pdf('Normal',single([0 1]),0,1)", "pdf('Normal',[0 1;2 3],0,[1 2;3 4])", "pdf('Half Normal',1,0,1)", "pdf(\"Normal\",0.5,0,1)",
          "cdf('normal',0.5,0,1,'upper')", "cdf('Exponential',[1 2],2,'upper')", "cdf('gamma',[1 2],2,3,'upper')", "cdf('foo',1)", "cdf('normal')", "cdf(1,2)", "cdf('normal',0.5)", "cdf('Poisson',[1 2],3,'upper')", "cdf('Uniform',[0.2 0.5],0,1,'upper')",
          "icdf('normal',0.5)", "icdf('foo',0.5)", "icdf('normal')", "icdf(2,0.5)", "icdf('Normal',[0.1 0.9],0,1,2)", "icdf('Uniform',[0.2 0.5],0,1)", "icdf('Hypergeometric',[0.2 0.5],20,5,8)", "icdf('t',[0.2 0.5],5)", "icdf('Half Normal',0.5,0,1)",
          "pdf('Normal',x(1:3),0,1)", "pdf('t',x(1:3),3)", "cdf('t',x(1:3),3,'upper')"]:
    L.append(f"r = {c};")
for c in ["random('Uniform',0,1,3,1)", "random('unif',2,5,[2 2])", "random('Exponential',2,3,1)", "random('exp',2,[1 3])", "random('Poisson',3,4,1)", "random('foo',1)", "random('n',1)", "random(1,2)", "random('Uniform',0,1)", "random('Uniform','a',1)", "random('Discrete Uniform',10,3,1)", "random('geo',0.3,3,1)", "random('Binomial',10,0.3,3,1)", "random('Uniform')"]:
    L.append(f"rng(7); r = {c};")
with open(os.path.join(here, "cases_gen.txt"), "w", encoding="utf-8", newline="\n") as f:
    f.write("\n".join(L) + "\n")
print(len(L))
